#include <windows.h>
#include <stdio.h>
static void sample(HDC dc,HBITMAP bitmap){BITMAP query={0};GetObjectW(bitmap,sizeof(query),&query);BITMAPINFO info={0};info.bmiHeader.biSize=40;info.bmiHeader.biWidth=query.bmWidth;info.bmiHeader.biHeight=-query.bmHeight;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;DWORD pixels[32]={0};int lines=GetDIBits(dc,bitmap,0,query.bmHeight,pixels,&info,0);printf("%ldx%ld depth%u lines%d pixels",query.bmWidth,query.bmHeight,query.bmBitsPixel,lines);for(int i=0;i<query.bmWidth*query.bmHeight;i++)printf(" %08lx",pixels[i]);puts("");}
int main(void){HDC dc=GetDC(NULL);DWORD values[]={0x80102030,0x80405060,0x80708090,0xffa0b0c0};HBITMAP src=CreateBitmap(2,2,1,32,values);sample(dc,src);for(int size=2;size<=4;size++){HBITMAP copy=CopyImage(src,IMAGE_BITMAP,size,size,0);sample(dc,copy);DeleteObject(copy);}HBITMAP same=CopyImage(src,IMAGE_BITMAP,0,0,LR_COPYRETURNORG);printf("returnorg %d\n",same==src);DeleteObject(same);BYTE mono[]={0x80,0,0x40,0};HBITMAP mask=CreateBitmap(2,2,1,1,mono),copy=CopyImage(mask,IMAGE_BITMAP,4,4,0);sample(dc,copy);DeleteObject(copy);DeleteObject(mask);DeleteObject(src);ReleaseDC(NULL,dc);return 0;}
